<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowDown, ArrowUp, ArrowUpDown, X } from '@lucide/vue'
import type { ResearchPageData } from './research.types'
import TacticalCompositeChart from './TacticalCompositeChart.vue'
const props = defineProps<{ data: ResearchPageData }>()
const period = ref<21 | 63 | 126>(63)
const tab = ref<'overview' | 'components' | 'performance'>('overview')
const selected = ref(0)
const expanded = ref(false)
const chart = computed(() => props.data.tacticalChart)
const dates = computed(() => chart.value?.dates.slice(-period.value) ?? [])
const prices = computed(() => chart.value?.price.slice(-period.value) ?? [])
const regimes = computed(() => chart.value?.regimes.slice(-period.value) ?? [])
const current = computed(() => regimes.value.at(-1) ?? 0)
const selectedSeries = computed(() => props.data.series[selected.value])
const counts = computed(() => [1, 0, -1].map((signal) => props.data.series.filter((item) => item.points.at(-1) === signal).length))
const signalName = (value: number) => value > 0 ? 'Positive' : value < 0 ? 'Negative' : 'Neutral'
const signalClass = (value: number) => value > 0 ? 'text-[var(--app-positive)] bg-[var(--app-positive)]/10' : value < 0 ? 'text-[var(--app-negative)] bg-[var(--app-negative)]/10' : 'text-[var(--app-text-muted)] bg-[var(--app-surface-muted)]'
const signalColor = (value: number) => value > 0 ? 'bg-[var(--app-positive)]' : value < 0 ? 'bg-[var(--app-negative)]' : 'bg-[var(--app-surface-muted)]'
const displayDate = (index: number) => dates.value[index] ? new Date(`${dates.value[index]}T12:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' }) : ''
type SortKey = 'name' | 'status'
const sortKey = ref<SortKey>('name')
const sortDirection = ref<'asc' | 'desc'>('asc')
const sortedSeries = computed(() => props.data.series.map((item, index) => ({ item, index })).sort((left, right) => {
  const leftValue = sortKey.value === 'name' ? left.item.name : left.item.status
  const rightValue = sortKey.value === 'name' ? right.item.name : right.item.status
  const result = leftValue.localeCompare(rightValue)
  return sortDirection.value === 'asc' ? result : -result
}))
function sortBy(key: SortKey) { if (sortKey.value === key) sortDirection.value = sortDirection.value === 'asc' ? 'desc' : 'asc'; else { sortKey.value = key; sortDirection.value = 'asc' } }
const horizons = computed(() => [5, 21, 63].filter((value) => value < period.value))
const performance = computed(() => [1, 0, -1].flatMap((state) => horizons.value.flatMap((horizon) => {
  const returns = prices.value.slice(0, -horizon).flatMap((price, index) => regimes.value[index] === state ? [(prices.value[index + horizon] / price - 1) * 100] : [])
  if (!returns.length) return []
  const sorted = [...returns].sort((left, right) => left - right)
  const middle = Math.floor(sorted.length / 2)
  const positive = returns.filter((value) => value > 0).length
  return [{ state, horizon, count: returns.length, average: returns.reduce((sum, value) => sum + value, 0) / returns.length, median: sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2, positive }]
})))
const signed = (value: number) => `${value > 0 ? '+' : ''}${value.toFixed(2)}%`
function select(index: number) { selected.value = index; tab.value = 'components' }
</script>
<template>
  <section class="space-y-4" data-testid="tactical-composite-content">
    <div class="flex flex-wrap items-center justify-between gap-3"><p class="text-xs text-[var(--app-text-muted)]">Illustrative data · Index levels and model signals are simulated.</p><div class="inline-flex items-center gap-0.5 rounded-md border border-[var(--app-border)] bg-[var(--app-surface-soft)] p-0.5" aria-label="Chart period"><button v-for="option in [21,63,126] as const" :key="option" type="button" class="h-7 rounded px-2.5 text-[.6875rem] font-semibold" :aria-pressed="period === option" :class="period === option ? 'bg-[var(--app-surface)] text-[var(--app-primary)] shadow-sm' : 'text-[var(--app-text-muted)] hover:text-[var(--app-primary)]'" @click="period = option">{{ option }} sessions</button></div></div>
    <div class="flex gap-6 overflow-x-auto border-b border-[var(--app-border)]" role="tablist" aria-label="Tactical Composite Trend Model views"><button v-for="item in [{key:'overview',label:'Model overview'},{key:'components',label:'7 components'},{key:'performance',label:'Performance'}] as const" :key="item.key" type="button" role="tab" class="whitespace-nowrap border-b-2 px-1 py-3 text-xs font-semibold" :class="tab === item.key ? 'border-[var(--app-primary)] text-[var(--app-primary)]' : 'border-transparent text-[var(--app-text-muted)]'" :aria-selected="tab === item.key" @click="tab = item.key">{{ item.label }}</button></div>
    <template v-if="tab === 'overview'"><div class="grid gap-4 2xl:grid-cols-[minmax(0,1fr)_290px]"><article class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-sm"><header class="flex items-start justify-between gap-3 border-b border-[var(--app-border)] px-3 py-3"><div><h2 class="font-semibold">Index and Tactical Regime</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Follow the S&amp;P 500 Index alongside positive, neutral and negative model states.</p></div><button type="button" aria-label="Expand Index and Tactical Regime" class="grid h-8 w-8 place-items-center rounded border border-[var(--app-border)] text-[var(--app-text-muted)] hover:text-[var(--app-primary)]" @click="expanded = true">↗</button></header><div class="px-3 py-3"><TacticalCompositeChart v-if="chart" :dates="chart.dates" :values="chart.price" :regimes="chart.regimes" :period="period" /></div><div class="border-t border-[var(--app-border)] px-5 py-3"><div class="mb-2 flex justify-between text-xs"><strong>Tactical signal</strong><span class="text-[var(--app-text-muted)]">Positive · Neutral · Negative</span></div><div class="flex h-3 gap-0.5" role="img" :aria-label="`Tactical signal history, ${period} sessions`"><span v-for="(value,index) in regimes" :key="index" class="min-w-0 flex-1 rounded-[1px]" :class="signalColor(value)" :title="`${displayDate(index)}: ${signalName(value)}`" /></div></div><footer class="border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-xs text-[var(--app-text-muted)]">The line shows the index level; its color shows the model state on each date.</footer></article><aside class="space-y-4"><section class="rounded-lg border border-[var(--app-border)] bg-[var(--app-primary-soft)] p-5"><span class="text-[.6875rem] font-bold uppercase tracking-wider text-[var(--app-text-muted)]">Tactical regime · demo</span><strong class="mt-2 block text-4xl" :class="signalClass(current).split(' ')[0]">{{ signalName(current) }}</strong><p class="mt-4 text-xs leading-5 text-[var(--app-text-muted)]">Read the current model state and compare it with the component signals below.</p><div class="mt-4 flex gap-4 text-xs text-[var(--app-text-muted)]"><span><b class="text-lg">{{ counts[0] }}</b> positive</span><span><b class="text-lg">{{ counts[1] }}</b> neutral</span><span><b class="text-lg">{{ counts[2] }}</b> negative</span></div></section><section class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-5"><h2 class="font-semibold">Explore the model</h2><p class="mt-3 text-xs leading-5 text-[var(--app-text-muted)]">Select a component to view its signal history. Open Performance to explore the simulated forward-return profile.</p><div class="mt-4 flex flex-wrap gap-3 text-xs"><span class="text-[var(--app-positive)]">● Positive</span><span class="text-[var(--app-text-muted)]">● Neutral</span><span class="text-[var(--app-negative)]">● Negative</span></div></section></aside></div></template>
    <div v-if="tab !== 'performance'" class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-semibold">{{ tab === 'overview' ? 'Seven components, one timeline' : 'Component signal histories' }}</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">{{ tab === 'overview' ? 'Read the current signal and the timing of its changes.' : 'Select a row to inspect its state transitions.' }}</p></div><button v-if="tab === 'overview'" type="button" class="rounded border border-[var(--app-border)] bg-[var(--app-primary-soft)] px-3 py-2 text-xs font-semibold text-[var(--app-primary)]" @click="tab = 'components'">Inspect components →</button><div v-else class="flex gap-3 text-xs"><span class="text-[var(--app-positive)]">● Positive</span><span class="text-[var(--app-text-muted)]">● Neutral</span><span class="text-[var(--app-negative)]">● Negative</span></div></div>
    <section v-if="tab !== 'performance'" class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-sm"><div class="overflow-x-auto"><table class="w-full min-w-[900px] border-collapse text-left text-[.8125rem]"><thead class="bg-[var(--app-surface-muted)] text-[.6875rem] font-semibold text-[var(--app-text-secondary)]"><tr class="border-b border-[var(--app-border)]"><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('name')">Model component<ArrowUp v-if="sortKey === 'name' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'name'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('status')">Current signal<ArrowUp v-if="sortKey === 'status' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'status'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="w-[40%] px-4 py-3">Signal history · {{ period }} sessions</th><th class="w-12 px-4 py-3" /></tr></thead><tbody><tr v-for="(entry,rowIndex) in sortedSeries" :key="entry.item.name" class="border-b border-[var(--app-border-muted)] last:border-0 hover:bg-[var(--app-surface-hover)]" :class="rowIndex % 2 ? 'bg-[var(--app-row-even)]' : ''"><td class="px-4 py-3"><button type="button" class="text-left font-semibold text-[var(--app-text-secondary)] hover:text-[var(--app-primary)]" @click="select(entry.index)">{{ entry.item.name }}</button><small class="mt-1 block text-[var(--app-text-muted)]">Component {{ entry.index + 1 }}</small></td><td class="px-4 py-3"><span class="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[.6875rem] font-bold" :class="signalClass(entry.item.points.at(-1) ?? 0)"><i class="h-1.5 w-1.5 rounded-full bg-current"/>{{ entry.item.status }}</span></td><td class="px-4 py-3"><div class="flex h-3 gap-0.5" role="img" :aria-label="`${entry.item.name} signal history`"><span v-for="(value,session) in entry.item.points.slice(-period)" :key="session" class="min-w-0 flex-1 rounded-[1px]" :class="signalColor(value)" :title="`${displayDate(session)}: ${signalName(value)}`" /></div></td><td class="px-4 py-3 text-right"><button type="button" :aria-label="`Inspect ${entry.item.name}`" class="h-6 w-6 rounded border border-[var(--app-border)] bg-[var(--app-surface)] text-sm leading-5 text-[var(--app-text-muted)] hover:bg-[var(--app-primary-soft)] hover:text-[var(--app-primary)]" @click="select(entry.index)">↗</button></td></tr></tbody></table></div></section>
    <section v-if="tab === 'components' && selectedSeries && chart" class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-5"><div class="flex items-center justify-between gap-3"><div><h2 class="font-semibold">{{ selectedSeries.name }}</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Illustrative state scale: +1 positive · 0 neutral · −1 negative</p></div><span class="rounded-full px-3 py-1 text-xs font-bold" :class="signalClass(selectedSeries.points.at(-1) ?? 0)">{{ selectedSeries.status }}</span></div><TacticalCompositeChart :dates="chart.dates" :values="selectedSeries.points" :period="period" signal /></section>
    <template v-if="tab === 'performance' && chart"><div class="rounded-lg border border-[var(--app-border)] bg-[var(--app-primary-soft)] p-4 text-xs text-[var(--app-text-secondary)]"><strong class="mr-2 text-[var(--app-primary)]">SIMULATED PERFORMANCE</strong>Calculated from the same {{ period }}-session demo series shown below. These figures illustrate the layout and are not a real strategy backtest.</div><article class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)]"><header class="flex items-start justify-between gap-3 border-b border-[var(--app-border)] px-3 py-3"><div><h2 class="font-semibold">Index and Model State</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">S&amp;P 500 Index · simulated index level · {{ displayDate(0) }} – {{ displayDate(period - 1) }}, 2026</p></div><button type="button" aria-label="Expand Index and Model State" class="grid h-8 w-8 place-items-center rounded border border-[var(--app-border)] text-[var(--app-text-muted)] hover:text-[var(--app-primary)]" @click="expanded = true">↗</button></header><div class="px-3 py-3"><TacticalCompositeChart :dates="chart.dates" :values="chart.price" :regimes="chart.regimes" :period="period" /></div><div class="border-t border-[var(--app-border)] px-5 py-3"><div class="mb-2 flex justify-between text-xs"><strong>Model state</strong><span>Green = positive · gray = neutral · rose = negative</span></div><div class="flex h-3 gap-0.5"><span v-for="(value,index) in regimes" :key="index" class="min-w-0 flex-1 rounded-[1px]" :class="signalColor(value)" :title="`${displayDate(index)}: ${signalName(value)}`" /></div></div></article><section class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)]"><header class="border-b border-[var(--app-border)] px-5 py-4"><h2 class="font-semibold">Forward returns by model state</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Each eligible daily observation is grouped by the state on that day.</p></header><div class="overflow-x-auto"><table class="w-full min-w-[700px] text-left text-[.8125rem]"><thead class="bg-[var(--app-surface-muted)] text-[.6875rem] font-semibold text-[var(--app-text-secondary)]"><tr class="border-b border-[var(--app-border)]"><th v-for="heading in ['Model state','Forward window','Observations','Average return','Median return','Positive outcomes']" :key="heading" class="px-4 py-3">{{ heading }}</th></tr></thead><tbody><tr v-for="(row,rowIndex) in performance" :key="`${row.state}-${row.horizon}`" class="border-b border-[var(--app-border-muted)] last:border-0 hover:bg-[var(--app-surface-hover)]" :class="rowIndex % 2 ? 'bg-[var(--app-row-even)]' : ''"><td class="px-4 py-3"><span class="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 font-bold" :class="signalClass(row.state)"><i class="h-1.5 w-1.5 rounded-full bg-current"/>{{ signalName(row.state) }}</span></td><td class="px-4 py-3">{{ row.horizon }} sessions</td><td class="px-4 py-3">{{ row.count }}</td><td class="px-4 py-3" :class="row.average >= 0 ? 'text-[var(--app-positive)]' : 'text-[var(--app-negative)]'">{{ signed(row.average) }}</td><td class="px-4 py-3" :class="row.median >= 0 ? 'text-[var(--app-positive)]' : 'text-[var(--app-negative)]'">{{ signed(row.median) }}</td><td class="px-4 py-3"><strong>{{ (row.positive / row.count * 100).toFixed(1) }}%</strong><small class="block text-[var(--app-text-muted)]">{{ row.positive }} / {{ row.count }} observations</small></td></tr></tbody></table></div><footer class="border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-xs leading-5 text-[var(--app-text-muted)]">Return: percentage change in the simulated index from the observation date to the end of the forward window. Positive outcomes: returns above zero ÷ eligible observations. Windows may overlap; dates without a full forward window are excluded.</footer></section></template>
    <Teleport to="body"><div v-if="expanded && chart" class="fixed inset-0 z-[80] grid place-items-center bg-[var(--app-overlay)] p-4" role="dialog" aria-modal="true" aria-label="Expanded tactical chart"><section class="w-full max-w-5xl rounded-lg bg-[var(--app-surface)] p-5 shadow-2xl"><div class="mb-4 flex justify-between"><h2 class="font-semibold">Index and Tactical Regime</h2><button type="button" aria-label="Close expanded chart" @click="expanded = false"><X :size="18" /></button></div><TacticalCompositeChart :dates="chart.dates" :values="chart.price" :regimes="chart.regimes" :period="period" /></section></div></Teleport>
  </section>
</template>
